// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken_,
        address nft_,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee_,
        uint16 feeRate_,
        bytes32 merkleRoot_,
        bool useOracle,
        bool payRoyalties_
    ) public {
        vm.assume(feeRate_ <= 5_000);

        c.initialize(
            baseToken_,
            nft_,
            virtualBase,
            virtualNft,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useOracle,
            payRoyalties_
        );

        assertTrue(c.feeRate() == feeRate_);
    }
}
